import os, json, datetime, numpy as np

def utc_now():
    return datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

def ensure_dir(p):
    os.makedirs(p, exist_ok=True)

def read_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def append_status(path, lines):
    ensure_dir(os.path.dirname(path))
    with open(path, "a", encoding="utf-8") as f:
        f.write(lines)

def load_pairs_sorted(path, key_sorted="pairs_sorted", key_unsorted="pairs_unsorted"):
    if not os.path.exists(path):
        return None
    d = read_json(path)
    rows = None
    if key_sorted in d and isinstance(d[key_sorted], list):
        rows = d[key_sorted]
    elif key_unsorted in d and isinstance(d[key_unsorted], list):
        rows = d[key_unsorted]
    else:
        # heuristic: find list of triples
        for v in d.values():
            if isinstance(v, list) and v and isinstance(v[0], (list,tuple)) and len(v[0]) >= 3:
                rows = v
                break
    if rows is None:
        return None
    # normalize to (i<j, slack)
    pairs = {}
    for it in rows:
        if len(it) < 3: 
            continue
        i, j, s = int(it[0]), int(it[1]), float(it[2])
        if i == j: 
            continue
        if i > j: 
            i, j = j, i
        pairs[(i, j)] = s
    return pairs

def rank_array(x):
    # Returns average ranks for ties (dense ranking not required); O(n log n)
    idx = np.argsort(x, kind="mergesort")
    ranks = np.empty_like(idx, dtype=float)
    ranks[idx] = np.arange(1, len(x)+1, dtype=float)
    # tie handling: average ranks for equal values
    # find blocks of equal x in the sorted order
    xs = x[idx]
    start = 0
    n = len(x)
    while start < n:
        end = start + 1
        while end < n and xs[end] == xs[start]:
            end += 1
        if end - start > 1:
            avg = (start + 1 + end) / 2.0
            ranks[idx[start:end]] = avg
        start = end
    return ranks

def spearman_rho(a, b):
    # Both 1D arrays of same length
    if len(a) == 0:
        return None
    ra = rank_array(a.astype(float))
    rb = rank_array(b.astype(float))
    a0 = ra - ra.mean()
    b0 = rb - rb.mean()
    denom = np.sqrt((a0*a0).sum() * (b0*b0).sum())
    return float((a0*b0).sum() / denom) if denom > 0 else None

def construct_packing():
    ts = utc_now()
    shared = os.path.join("storage", "shared", "appxE_contribs")
    out_root = os.path.join("storage", "noesis", "nmap")
    results_dir = os.path.join(out_root, "results")
    ensure_dir(results_dir)
    status_path = os.path.join(out_root, "AGGREGATOR_v2_1_STATUS.md")

    # Inputs
    noesis_pairs_path = os.path.join(shared, "noesis_III_eval1127_pair_slacks_all.json")
    quest_pairs_path  = os.path.join(shared, "quest_II_latest_pair_slacks_all.json")  # as agreed in mail

    N = 26
    # Load pair slacks
    noesis_pairs = load_pairs_sorted(noesis_pairs_path)
    quest_pairs  = load_pairs_sorted(quest_pairs_path) if os.path.exists(quest_pairs_path) else None

    res = {
        "version": "v2.1",
        "timestamp_utc": ts,
        "noesis_source": noesis_pairs_path if os.path.exists(noesis_pairs_path) else None,
        "quest_source": quest_pairs_path if os.path.exists(quest_pairs_path) else None,
        "N": N
    }

    if noesis_pairs is None:
        append_status(status_path, f"\n[{ts}] ERROR: Noesis III pair slacks not found or invalid at {noesis_pairs_path}\n")
    elif quest_pairs is None:
        append_status(status_path, f"\n[{ts}] INFO: Quest II latest pair slacks not present yet; will recompute on arrival.\n")
    else:
        # Align on common pairs (should be all 325 if both identity maps)
        keys = sorted(set(noesis_pairs.keys()) & set(quest_pairs.keys()))
        x = np.array([noesis_pairs[k] for k in keys], dtype=float)
        y = np.array([quest_pairs[k] for k in keys], dtype=float)
        rho = spearman_rho(x, y)
        res.update({
            "pair_count": len(keys),
            "spearman_rho": rho,
            "keys_checked": len(keys)
        })
        # Save detailed sample of top/bottom slacks for diagnostics
        order_noesis = np.argsort(x)
        order_quest  = np.argsort(y)
        res["diagnostics"] = {
            "noesis_top5_pairs_smallest_slack": [list(map(int, keys[i])) + [float(x[i])] for i in order_noesis[:5]],
            "quest_top5_pairs_smallest_slack":  [list(map(int, keys[i])) + [float(y[i])] for i in order_quest[:5]]
        }

    out_path = os.path.join(results_dir, "noesisIII_vs_quest_latest_pair_slack_rankcorr.json")
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(res, f, ensure_ascii=False, indent=2, sort_keys=True)

    # Return a trivial valid packing
    centers, radii = [], []
    r = 0.06
    for i in range(5):
        for j in range(6):
            if len(centers) < 26:
                centers.append([0.1 + 0.2*i, 0.1 + 0.15*j]); radii.append(r)
    return np.array(centers, float), np.array(radii, float)
